const raw = $input.first().json;
const body = raw.body || raw;
const args = body.args || {};

function normPhone(p) {
  const d = String(p || '').replace(/\D/g, '');
  if (!d) return '';
  if (d.length === 10) return '91' + d;
  return d;
}

const from = normPhone(body.from || args.caller_phone);
const callId = String(body.call_id || args.call_id || `CALL-${Date.now()}`);
let summary = String(args.summary || '').trim();
const conversationFull = String(args.conversation_full || args.transcript || args.conversation || '').trim();
let preview = String(args.conversation_preview || '').trim();
if (!preview && conversationFull) {
  preview = conversationFull.replace(/\n/g, ' ').slice(0, 280);
  if (conversationFull.length > 280) preview += '…';
}
const turns = Number(args.transcript_turns || 0) || (conversationFull ? conversationFull.split('\n').filter(Boolean).length : 0);
const outcome = args.outcome || args.reason || 'Ended';
const intent = args.caller_intent || 'General enquiry';
const durationSec = Number(args.duration_sec || 0);
const duration = args.duration || (durationSec ? `${durationSec} sec` : '');
const date = args.date || new Date().toISOString().slice(0, 10);
const timeIst = args.time_ist || '';
const business = body.business_name || 'ResilienceSoft';
const notify = normPhone(args.notify_whatsapp || body.notify_whatsapp || '');
const direction = args.direction || body.direction || 'inbound';
const language = args.language || body.language || 'en';
const appt = args.appointment_booked || 'no';
const lead = args.lead_captured || 'no';
const followUp = args.follow_up || 'none';

if (!summary && preview) {
  summary = `Caller intent: ${intent}. ${preview.replace(/^\[\d+ turns\]\s*/, '')} Follow-up: ${followUp}.`;
}
if (!summary) {
  summary = 'No clear summary captured. Review conversation or call back.';
}

const waText = [
  `📞 *${business} — Call Summary*`,
  `Date: ${date}${timeIst ? '  ' + timeIst : ''}`,
  `Caller: ${from || 'unknown'}`,
  `Duration: ${duration}`,
  `Language: ${language} | Direction: ${direction}`,
  `Outcome: ${outcome}`,
  `Looking for: ${intent}`,
  `Appointment: ${appt} | Lead: ${lead} | Follow-up: ${followUp}`,
  '',
  '*Summary*',
  summary,
  preview ? '\n*Snippet*\n' + preview : ''
].join('\n').trim();

const waBody = notify ? {
  messageObject: {
    messaging_product: 'whatsapp',
    to: notify,
    type: 'text',
    text: { body: waText }
  },
  enableLog: true
} : null;

return [{
  json: {
    call_id: callId,
    date,
    time_ist: timeIst,
    caller_phone: from,
    duration_sec: durationSec,
    duration,
    direction,
    language,
    outcome,
    caller_intent: intent,
    summary,
    conversation_preview: preview,
    conversation_full: conversationFull,
    transcript_turns: turns,
    transcript_ref: 'voice_transcripts',
    appointment_booked: appt,
    lead_captured: lead,
    follow_up: followUp,
    business_name: business,
    notify_whatsapp: notify,
    waBody,
    hasWhatsApp: !!waBody
  }
}];

const raw = $input.first().json;
const body = raw.body || raw;
const action = body.action || 'unknown';
const args = body.args || {};
const callId = body.call_id || `CALL-${Date.now()}`;
const from = String(body.from || '').replace(/\D/g, '');
const business = body.business_name || 'ResilienceSoft';
const now = new Date();
const date = now.toISOString().slice(0, 10);

let response;
let sheetRow = null;

switch (action) {
  case 'lookup_knowledge': {
    const q = String(args.query || '').trim();
    response = {
      status: 'ok',
      action,
      query: q,
      results: '',
      message: 'No n8n knowledge index configured. Voice-agent should answer using local business_knowledge.md search. Add a Google Sheet tab knowledge_faq or HTTP node to your backend for extended RAG.',
    };
    break;
  }
  case 'book_appointment': {
    const parts = [];
    if (args.date) parts.push(`for ${args.date}`);
    if (args.time) parts.push(`at ${args.time}`);
    response = {
      status: 'confirmed',
      action,
      message: (`Appointment confirmed ${parts.join(' ')}`.trim() || 'Appointment noted') + '.',
    };
    sheetRow = {
      call_id: callId,
      date,
      time_ist: '',
      caller_phone: from,
      action_type: action,
      name: args.name || '',
      phone: args.phone || from,
      interest: '',
      service: args.service || '',
      appt_date: args.date || '',
      appt_time: args.time || '',
      notes: '',
      status: 'confirmed',
      business_name: business,
    };
    break;
  }
  case 'create_lead': {
    response = {
      status: 'lead_created',
      action,
      message: 'Lead captured. The team will follow up shortly.',
    };
    sheetRow = {
      call_id: callId,
      date,
      time_ist: '',
      caller_phone: from,
      action_type: action,
      name: args.name || '',
      phone: args.phone || from,
      interest: args.interest || '',
      service: '',
      appt_date: '',
      appt_time: '',
      notes: args.notes || '',
      status: 'lead_created',
      business_name: business,
    };
    break;
  }
  case 'send_notification': {
    response = {
      status: 'notified',
      action,
      message: 'Your message has been passed to the team.',
    };
    sheetRow = {
      call_id: callId,
      date,
      time_ist: '',
      caller_phone: from,
      action_type: action,
      name: '',
      phone: from,
      interest: '',
      service: '',
      appt_date: '',
      appt_time: '',
      notes: args.message || '',
      status: 'notified',
      business_name: business,
    };
    break;
  }
  default: {
    response = { status: 'ok', action, message: `Action '${action}' received.` };
  }
}

return [{ json: { ...response, sheetRow } }];

const h = $('Handle Action').first().json;
const { sheetRow, ...response } = h;
return [{ json: response }];
